def comps(g):
    H=len(g);W=len(g[0]);seen=set();cs=[]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v==0 or (i,j) in seen: continue
            col=v;stack=[(i,j)];cells=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen or g[y][x]!=col: continue
                seen.add((y,x));cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W: stack.append((ny,nx))
            cs.append((col,cells))
    return cs

