import os,re,json
from collections import deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[]
        for line in t[m.end():].split('\n'):
            p=line.split()
            if len(p)==w and all(x.isdigit() for x in p): rows.append([int(x) for x in p])
            else: break
        if len(rows)==h and k not in G: G[k]=rows
    return G
G=load(); print(sorted(G))
def comps_of(g):
    h=len(g); w=len(g[0]); seen=[[False]*w for _ in range(h)]; res=[]
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v!=0 and v!=2 and not seen[i][j]:
                st=deque([(i,j)]); seen[i][j]=True; cells=[]
                while st:
                    y,x=st.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                res.append((v,cells))
    return res
def f(g):
    h=len(g); w=len(g[0])
    wall=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    # find full wall line
    for i in range(h):
        if all(g[i][j]==2 for j in range(w)): dr,dc=1,0; break
    else:
        for j in range(w):
            if all(g[i][j]==2 for i in range(h)): dr,dc=0,1; break
    occ={v:set(ps) for v,ps in comps_of(g)}
    blocked=lambda ps: any(not(0<=a+h*0<h and 0<=b+w*0<w) or (a,b) in wallset for a,b in ps) if False else False
    moved=True
