def pack(g,dc,order_key=lambda c:(min(b for a,b in c), min(a for a,b in c))):
    # sequential: order components, each slides until touching wall or placed objects
    h,w=len(g),len(g[0])
    occ=[(v,set(map(tuple,ps))) for v,ps in comps_of(g)]
    wallset={(i,j) for i in range(h) for j in range(w) if g[i][j]==2}
    occ.sort(key=order_key)
    placed={}
    occupied=set()
    for vv,sp in occ:
        cur=list(sp)
        while True:
            nxt=[(a,b+dc) for a,b in cur]
            if any(not(0<=a<h and 0<=b<w) or (a,b) in wallset or (a,b) in occupied for a,b in nxt): break
            cur=nxt
        placed[vv]=cur; occupied|=set(cur)
    out=[[0]*w for _ in range(h)]
    for i,j in wallset: out[i][j]=2
    for v,ps in placed.values():
        for a,b in ps: out[a][b]=v
    return out
